pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Give user ether and deposit with _unlockTime = 0
        address user = address(0x1234);
        vm.deal(user, 2 ether);
        vm.prank(user);
        c.Put{value: 1 ether}(0);

        // Now attempt Collect(1 ether). In reference, unlockTime = block.timestamp, so block.timestamp > unlockTime is false, Collect reverts.
        // In mutant, unlockTime = 0, so Collect succeeds.
        bool success;
        vm.prank(user);
        try c.Collect(1 ether) {
            success = true;
        } catch {
            success = false;
        }

        // Reference contract makes Collect revert, mutant makes it succeed.
        // We want: assertTrue(success) would pass on mutant but fail on reference.
        // Actually we need one assertion that reference holds and mutant breaks.
        // For reference, success == false; thus assertFalse(success) holds for reference, fails for mutant.
        assertFalse(success);
    }
}

