        c.Collect(1 ether);

        // The reference contract transfers 1 ether to user, so c.balance drops by 1 ether.
        // Bug transfers 0 ether, so c.balance stays 2 ether (initial 2 - 0 = 2).
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == 0 wei, "Balance should be 0 after correct Collect");
    }
}

